import * as THREE from 'three';

/**
 * Build a THREE.Shape whose outline is an n-pointed star made from
 * alternating outer/inner vertices.
 *
 * @param {number} starPoints number of star points
 * @param {number} outerRadius radius at the star tips
 * @param {number} innerRadius radius at the valleys between tips
 * @returns {THREE.Shape}
 */
export function starShape(starPoints, outerRadius, innerRadius) {
  const shape = new THREE.Shape();
  const total = 2 * starPoints;
  for (let i = 0; i < total; i++) {
    // Start each point's tip at angle 0 so tips are symmetric about +x.
    const halfStep = Math.PI / starPoints;
    const angle = i * halfStep;
    const r = i % 2 === 0 ? outerRadius : innerRadius;
    const x = r * Math.cos(angle);
    const y = r * Math.sin(angle);
    if (i === 0) {
      shape.moveTo(x, y);
    } else {
      shape.lineTo(x, y);
    }
  }
  shape.closePath();
  return shape;
}

/**
 * Outline of an n-pointed star as an array of THREE.Vector2 points.
 * Returns exactly 2 * starPoints vertices alternating between the
 * default outer (0.6) and inner (0.25) unit-scaled radii.
 *
 * @param {number} starPoints
 * @param {number} [outerRadius=0.6]
 * @param {number} [innerRadius=0.25]
 * @returns {THREE.Vector2[]}
 */
export function starOutline(starPoints, outerRadius = 0.6, innerRadius = 0.25) {
  return starShape(starPoints, outerRadius, innerRadius).getPoints();
}

/**
 * Build a commemorative coin: a cylindrical blank with a raised star
 * relief extruded on its top face.
 *
 * @param {{ radius?: number, thickness?: number, starPoints?: number, reliefHeight?: number }} [options]
 * @returns {{
 *   group: THREE.Group,
 *   blank: THREE.Mesh,
 *   star: THREE.Mesh,
 *   shape: THREE.Shape
 * }}
 */
export function buildCoin({
  radius = 3,
  thickness = 0.4,
  starPoints = 5,
  reliefHeight = 0.15,
} = {}) {
  if (radius <= 0) throw new Error('radius must be positive');
  if (thickness <= 0) throw new Error('thickness must be positive');
  if (reliefHeight < 0) throw new Error('reliefHeight must be non-negative');
  if (!Number.isInteger(starPoints) || starPoints < 2) {
    throw new Error('starPoints must be an integer >= 2');
  }

  const group = new THREE.Group();

  // Cylindrical blank centered on the origin: top face sits at y = thickness / 2.
  const blankGeometry = new THREE.CylinderGeometry(radius, radius, thickness, 64);
  const blankMaterial = new THREE.MeshStandardMaterial({ color: 0xd4af37, metalness: 0.9, roughness: 0.3 });
  const blank = new THREE.Mesh(blankGeometry, blankMaterial);
  group.add(blank);

  // Star relief extruded upward from the blank's top face.
  const shape = starShape(starPoints, 0.6 * radius, 0.25 * radius);
  const starGeometry = new THREE.ExtrudeGeometry(shape, {
    depth: reliefHeight,
    bevelEnabled: false,
    curveSegments: 1,
  });
  // ExtrudeGeometry grows along +z; rotate so it grows along +y.
  starGeometry.rotateX(-Math.PI / 2);

  const starMaterial = new THREE.MeshStandardMaterial({ color: 0xf5d76e, metalness: 0.95, roughness: 0.2 });
  const star = new THREE.Mesh(starGeometry, starMaterial);
  star.position.y = thickness / 2;
  group.add(star);

  return { group, blank, star, shape };
}

