import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { buildCoin, starOutline } from '../src/coin.js';

describe('starOutline', () => {
  it('returns 2 * starPoints vertices alternating between the two radii', () => {
    const outer = 0.6;
    const inner = 0.25;
    const points = starOutline(5);
    expect(points).toHaveLength(10);
    for (let i = 0; i < points.length; i++) {
      const r = Math.hypot(points[i].x, points[i].y);
      const expected = i % 2 === 0 ? outer : inner;
      expect(Math.abs(r - expected)).toBeLessThanOrEqual(1e-9);
    }
  });

  it('changing starPoints from 5 to 7 changes the outline to 14 points', () => {
    expect(starOutline(5)).toHaveLength(10);
    expect(starOutline(7)).toHaveLength(14);
  });
});

describe('buildCoin', () => {
  const { group, blank, star, shape } = buildCoin({});

  it('shape has 2*starPoints vertices alternating between the two radii', () => {
    const radius = 3;
    const outer = 0.6 * radius;
    const inner = 0.25 * radius;
    const pts = shape.getPoints();
    expect(pts).toHaveLength(2 * 5);
    for (let i = 0; i < pts.length; i++) {
      const r = Math.hypot(pts[i].x, pts[i].y);
      const expected = i % 2 === 0 ? outer : inner;
      expect(Math.abs(r - expected)).toBeLessThanOrEqual(1e-9);
    }
  });

  it('star relief sits on the top face with height reliefHeight', () => {
    const thickness = 0.4;
    const topY = thickness / 2;
    star.updateWorldMatrix(true, false);
    const box = new THREE.Box3().setFromObject(star);
    expect(Math.abs(box.min.y - topY)).toBeLessThanOrEqual(1e-6);
    expect(Math.abs(box.max.y - (topY + 0.15))).toBeLessThanOrEqual(1e-6);
  });

  it('star xz extent stays inside the coin radius', () => {
    star.updateWorldMatrix(true, false);
    const box = new THREE.Box3().setFromObject(star);
    const maxR = Math.max(
      box.min.length() > 0 ? 0 : 0,
      Math.hypot(box.max.x, box.max.z),
      Math.hypot(box.min.x, box.min.z),
    );
    expect(maxR).toBeLessThanOrEqual(3);
  });

  it('whole coin Box3 height equals thickness + reliefHeight', () => {
    group.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(group);
    expect(box.max.y - box.min.y).toBeCloseTo(0.4 + 0.15, 9);
  });
});

